// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.bulk;

/**
 * Sizes the work units of adaptive bulk-load sources from the memory budget, so the number of chunks, leaves and runs
 * grows with input size divided by available memory instead of input size divided by a fixed record count.
 */
final class AdaptiveChunkSizing {

	/** Upper bound for one work unit, so a single task stays short enough for the controller to adapt. */
	static final long MAXIMUM_CHUNK_BYTES = 16L * 1024L * 1024L;

	private AdaptiveChunkSizing() {
	}

	/**
	 * Returns the retained-byte target for one work unit: a quarter of the budget shared by every task that can be
	 * outstanding at once, clamped to {@code [minimumBytes, MAXIMUM_CHUNK_BYTES]}.
	 */
	static long chunkTargetBytes(long memoryBudgetBytes, int outstandingTasks, long minimumBytes) {
		if (memoryBudgetBytes <= 0L || minimumBytes <= 0L) {
			throw new IllegalArgumentException("chunk sizing inputs must be positive");
		}
		long share = memoryBudgetBytes / (4L * Math.max(1, outstandingTasks));
		return Math.max(minimumBytes, Math.min(MAXIMUM_CHUNK_BYTES, share));
	}

	/** Returns the record cap for a work unit of {@code targetBytes} whose records retain at least the minimum. */
	static int recordLimit(long targetBytes, long minimumRecordBytes) {
		if (targetBytes <= 0L || minimumRecordBytes <= 0L) {
			throw new IllegalArgumentException("record limit inputs must be positive");
		}
		return (int) Math.max(1L, Math.min(Integer.MAX_VALUE - 8L, targetBytes / minimumRecordBytes + 1L));
	}
}
